/**
 * Per-key exclusive execution queue.
 *
 * WhatsApp commands for a single user (session state, OTP verification,
 * strategy changes, deposit/withdraw transactions) all read and mutate the
 * same in-memory session record. Two messages arriving close together for
 * the same phone number can otherwise race through that state and leave it
 * inconsistent, or produce out-of-order acknowledgements.
 *
 * `runExclusive` serializes tasks sharing the same key so they run strictly
 * one at a time, in arrival order, while tasks for different keys (i.e.
 * different users) continue to run fully in parallel.
 */

type Task<T> = () => Promise<T>;

const tails = new Map<string, Promise<void>>();

export function runExclusive<T>(key: string, task: Task<T>): Promise<T> {
  const previous = tails.get(key) ?? Promise.resolve();

  // Run the next task once the previous one has *settled*, regardless of
  // whether it succeeded or failed - a failed command must never leave a
  // permanent lock blocking the user's next message.
  const run = previous.then(task, task);

  const settled = run.then(
    () => undefined,
    () => undefined
  );
  tails.set(key, settled);

  // Avoid unbounded growth for users who stop messaging: once this is the
  // last queued task for the key and it has settled, drop the entry.
  settled.then(() => {
    if (tails.get(key) === settled) {
      tails.delete(key);
    }
  });

  return run;
}

/** Test/diagnostic helper - not used in production code paths. */
export function pendingLockCount(): number {
  return tails.size;
}

import { ParsedIntent } from './intentParser';

/**
 * Strategy symbols accepted by the vault's `set_user_strategy`.
 * Mirrors the `InvalidStrategy` check in neurowealth-vault/contracts/vault/src/lib.rs.
 */
export const VALID_STRATEGIES = ['conservative', 'balanced', 'growth'] as const;
export type Strategy = (typeof VALID_STRATEGIES)[number];

/** USDC on Stellar uses 7 decimal places (1 USDC = 10_000_000 stroops). */
export const USDC_DECIMALS = 7;
const STROOPS_PER_USDC = 10 ** USDC_DECIMALS;

/**
 * Contract defaults written by `initialize` (all values in USDC stroops).
 * Keep in sync with DEFAULT_MIN_DEPOSIT / DEFAULT_MAX_DEPOSIT /
 * DEFAULT_USER_DEPOSIT_CAP / DEFAULT_TVL_CAP in lib.rs.
 */
export const CONTRACT_DEFAULT_LIMITS_STROOPS = {
  minDeposit: 1_000_000,          // 0.1 USDC
  maxDeposit: 10_000_000_000,     // 1,000 USDC
  userDepositCap: 10_000_000_000, // 1,000 USDC
  tvlCap: 100_000_000_000,        // 10,000 USDC
};

/** Deposit limits in whole USDC, as enforced by the vault contract. */
export interface ContractLimits {
  minDeposit: number;
  maxDeposit: number;
  userDepositCap: number;
  tvlCap: number;
}

function readStroopsEnv(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === '') return fallback;
  const value = Number(raw);
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new Error(`${name} must be a positive integer amount in stroops (got "${raw}")`);
  }
  return value;
}

/**
 * Returns the vault's deposit limits in USDC.
 *
 * Defaults mirror the contract's `initialize` values. When the owner changes
 * limits on-chain (`set_deposit_limits`, `set_user_deposit_cap`,
 * `set_tvl_cap`), set the matching env vars (in stroops, the same unit as the
 * contract getters `get_min_deposit`, `get_max_deposit`,
 * `get_user_deposit_cap`, `get_tvl_cap`) so the bot rejects out-of-range
 * requests before submitting a transaction.
 */
export function getContractLimits(): ContractLimits {
  const d = CONTRACT_DEFAULT_LIMITS_STROOPS;
  return {
    minDeposit: readStroopsEnv('VAULT_MIN_DEPOSIT', d.minDeposit) / STROOPS_PER_USDC,
    maxDeposit: readStroopsEnv('VAULT_MAX_DEPOSIT', d.maxDeposit) / STROOPS_PER_USDC,
    userDepositCap: readStroopsEnv('VAULT_USER_DEPOSIT_CAP', d.userDepositCap) / STROOPS_PER_USDC,
    tvlCap: readStroopsEnv('VAULT_TVL_CAP', d.tvlCap) / STROOPS_PER_USDC,
  };
}

export function isValidStrategy(name: string | undefined): name is Strategy {
  return name !== undefined && (VALID_STRATEGIES as readonly string[]).includes(name);
}

export type ValidationResult = { ok: true } | { ok: false; error: string };

function formatUsdc(value: number): string {
  return value.toLocaleString('en-US', { maximumFractionDigits: USDC_DECIMALS });
}

function validateAmount(amount: number | undefined, action: 'deposit' | 'withdraw'): ValidationResult {
  if (amount === undefined) {
    return { ok: false, error: `Please include an amount, e.g. "${action} 50 USDC".` };
  }
  if (!Number.isFinite(amount) || amount <= 0) {
    return { ok: false, error: `The ${action} amount must be greater than 0 USDC.` };
  }
  // Reject precision the contract cannot represent (sub-stroop amounts).
  const stroops = amount * STROOPS_PER_USDC;
  if (Math.abs(stroops - Math.round(stroops)) > 1e-6) {
    return { ok: false, error: `USDC supports at most ${USDC_DECIMALS} decimal places.` };
  }
  return { ok: true };
}

/**
 * Validates a parsed intent against the vault contract's caps and accepted
 * strategy names so invalid requests are rejected in chat instead of failing
 * on-chain. Intents that carry no amount or strategy always pass.
 */
export function validateIntent(
  intent: ParsedIntent,
  limits: ContractLimits = getContractLimits()
): ValidationResult {
  switch (intent.type) {
    case 'DEPOSIT': {
      const amountCheck = validateAmount(intent.amount, 'deposit');
      if (!amountCheck.ok) return amountCheck;
      const amount = intent.amount as number;
      if (amount < limits.minDeposit) {
        return { ok: false, error: `Minimum deposit is ${formatUsdc(limits.minDeposit)} USDC.` };
      }
      if (amount > limits.maxDeposit) {
        return { ok: false, error: `Maximum single deposit is ${formatUsdc(limits.maxDeposit)} USDC.` };
      }
      if (amount > limits.userDepositCap) {
        return { ok: false, error: `Deposits are capped at ${formatUsdc(limits.userDepositCap)} USDC per user.` };
      }
      if (amount > limits.tvlCap) {
        return { ok: false, error: `This exceeds the vault's total deposit cap of ${formatUsdc(limits.tvlCap)} USDC.` };
      }
      if (intent.strategy !== undefined && !isValidStrategy(intent.strategy)) {
        return { ok: false, error: invalidStrategyMessage(intent.strategy) };
      }
      return { ok: true };
    }
    case 'WITHDRAW': {
      if (intent.withdrawAll) return { ok: true };
      return validateAmount(intent.amount, 'withdraw');
    }
    case 'STRATEGY': {
      if (!isValidStrategy(intent.strategy)) {
        return { ok: false, error: invalidStrategyMessage(intent.strategy) };
      }
      return { ok: true };
    }
    default:
      return { ok: true };
  }
}

function invalidStrategyMessage(name: string | undefined): string {
  const options = VALID_STRATEGIES.map((s) => `"${s}"`).join(', ');
  return name
    ? `"${name}" is not a valid strategy. Choose one of ${options}.`
    : `Please name a strategy: ${options}.`;
}

import crypto from 'crypto';
import { KeyEntry, loadKeyring } from './keyring';

const ALGORITHM = 'aes-256-gcm';

function getEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`${name} must be set; refusing to use an unsafe production default`);
  }
  return value;
}

/** Validates the crypto-related environment; throws with a clear message when unusable. */
export function assertConfig(): void {
  loadKeyring();
  getEnv('PHONE_HASH_SALT');
}

/**
 * Hashes phone number to ensure PII privacy at rest.
 * Uses SHA-256 with a deployment-provided salt.
 */
export function hashPhoneNumber(phone: string): string {
  const salt = getEnv('PHONE_HASH_SALT');
  const hashedSalt = crypto.createHash('sha256').update(salt).digest('hex');
  return crypto.createHash('sha256').update(phone + hashedSalt).digest('hex');
}

/** Envelope fields persisted next to the ciphertext (#944). */
export interface EnvelopeFields {
  /** Per-wallet data-encryption key, AES-256-GCM-wrapped by the KEK. */
  wrappedDek: string;
  dekIv: string;
  dekTag: string;
  /** Version label of the KEK that wrapped the DEK. */
  keyVersion: string;
}

export interface EncryptedSecret extends Partial<EnvelopeFields> {
  encryptedData: string;
  iv: string;
  tag: string;
}

// ── KEK derivation / DEK wrapping ───────────────────────────────────────────
// wrapDek/unwrapDek are the KMS/HSM seam: a managed key service replaces just
// these two functions, with `keyVersion` carrying the provider's key id.

const kekCache = new Map<string, Buffer>();

function deriveKek(entry: KeyEntry): Buffer {
  const cacheKey = crypto.createHash('sha256').update(`${entry.version}\0${entry.material}`).digest('hex');
  let kek = kekCache.get(cacheKey);
  if (!kek) {
    kek = crypto.scryptSync(entry.material, `neurowealth-kek:${entry.version}`, 32);
    kekCache.set(cacheKey, kek);
  }
  return kek;
}

function wrapDek(dek: Buffer, entry: KeyEntry): Pick<EnvelopeFields, 'wrappedDek' | 'dekIv' | 'dekTag'> {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, deriveKek(entry), iv);
  // Binding the version as AAD makes a swapped key_version label fail loudly.
  cipher.setAAD(Buffer.from(`kek:${entry.version}`));
  const wrapped = Buffer.concat([cipher.update(dek), cipher.final()]);
  return {
    wrappedDek: wrapped.toString('hex'),
    dekIv: iv.toString('hex'),
    dekTag: cipher.getAuthTag().toString('hex'),
  };
}

function unwrapDek(envelope: EnvelopeFields, entry: KeyEntry): Buffer {
  const decipher = crypto.createDecipheriv(ALGORITHM, deriveKek(entry), Buffer.from(envelope.dekIv, 'hex'));
  decipher.setAAD(Buffer.from(`kek:${entry.version}`));
  decipher.setAuthTag(Buffer.from(envelope.dekTag, 'hex'));
  return Buffer.concat([decipher.update(Buffer.from(envelope.wrappedDek, 'hex')), decipher.final()]);
}

function findKey(version: string): KeyEntry {
  const ring = loadKeyring();
  const entry = [ring.current, ...ring.retired].find((e) => e.version === version);
  if (!entry) {
    throw new Error(
      `No key configured for encryption key version "${version}"; add it to ENCRYPTION_KEY_RETIRED to decrypt this record`
    );
  }
  return entry;
}

function openWithDek(dek: Buffer, encryptedData: string, iv: string, tag: string): string {
  const decipher = crypto.createDecipheriv(ALGORITHM, dek, Buffer.from(iv, 'hex'));
  decipher.setAuthTag(Buffer.from(tag, 'hex'));
  let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

/** Pre-#944 records: AES key = scrypt(ENCRYPTION_KEY, 'salt'), no per-record DEK. */
function decryptLegacy(encryptedData: string, iv: string, tag: string): string {
  const ring = loadKeyring();
  let lastError: unknown;
  // Legacy rows carry no version label, so try the current key, then retired ones.
  for (const entry of [ring.current, ...ring.retired]) {
    try {
      return openWithDek(crypto.scryptSync(entry.material, 'salt', 32), encryptedData, iv, tag);
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError instanceof Error ? lastError : new Error('Unable to decrypt legacy secret');
}

/**
 * Encrypts sensitive custodial Stellar secret key before saving to storage.
 * A fresh DEK encrypts the secret and the current KEK wraps the DEK.
 */
export function encryptSecretKey(secretKey: string): EncryptedSecret & EnvelopeFields {
  const { current } = loadKeyring();
  const dek = crypto.randomBytes(32);
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, dek, iv);

  let encrypted = cipher.update(secretKey, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');

  return {
    encryptedData: encrypted,
    iv: iv.toString('hex'),
    tag,
    ...wrapDek(dek, current),
    keyVersion: current.version,
  };
}

/**
 * Decrypts encrypted custodial Stellar secret key for transaction signing.
 * Pass the envelope fields for records written since #944; omit them for
 * legacy records. Never log or expose the output of this function.
 */
export function decryptSecretKey(
  encryptedData: string,
  iv: string,
  tag: string,
  envelope?: Partial<EnvelopeFields>
): string {
  if (envelope?.wrappedDek && envelope.dekIv && envelope.dekTag && envelope.keyVersion) {
    const dek = unwrapDek(envelope as EnvelopeFields, findKey(envelope.keyVersion));
    return openWithDek(dek, encryptedData, iv, tag);
  }
  return decryptLegacy(encryptedData, iv, tag);
}

/** True when the record is already wrapped by the current KEK. */
export function isCurrentKeyVersion(secret: EncryptedSecret): boolean {
  return Boolean(secret.wrappedDek) && secret.keyVersion === loadKeyring().current.version;
}

/**
 * Brings a stored secret up to date with the current KEK. Envelope records
 * only get their DEK re-wrapped (ciphertext untouched); legacy records are
 * decrypted once and re-encrypted into the envelope format.
 */
export function rewrapSecret(secret: EncryptedSecret): EncryptedSecret & EnvelopeFields {
  const { current } = loadKeyring();

  if (secret.wrappedDek && secret.dekIv && secret.dekTag && secret.keyVersion) {
    const dek = unwrapDek(secret as EnvelopeFields, findKey(secret.keyVersion));
    return {
      encryptedData: secret.encryptedData,
      iv: secret.iv,
      tag: secret.tag,
      ...wrapDek(dek, current),
      keyVersion: current.version,
    };
  }

  return encryptSecretKey(decryptLegacy(secret.encryptedData, secret.iv, secret.tag));
}

// ── Short-lived field encryption (no per-record envelope columns) ───────────
// Used for values stored in a plain (data, iv, tag) triple, such as the
// recipient of a pending message delivery. The key is derived from the KEK of
// the version prefixed to the ciphertext, so these rows survive rotation as
// long as that version stays in ENCRYPTION_KEY_RETIRED.

const FIELD_PREFIX = /^([A-Za-z0-9_.-]{1,32}):([0-9a-f]+)$/;

function fieldKey(entry: KeyEntry): Buffer {
  return crypto.createHmac('sha256', deriveKek(entry)).update('neurowealth-field-encryption').digest();
}

export function encryptField(plaintext: string): { encryptedData: string; iv: string; tag: string } {
  const { current } = loadKeyring();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, fieldKey(current), iv);
  const encrypted = cipher.update(plaintext, 'utf8', 'hex') + cipher.final('hex');
  return {
    encryptedData: `${current.version}:${encrypted}`,
    iv: iv.toString('hex'),
    tag: cipher.getAuthTag().toString('hex'),
  };
}

export function decryptField(encryptedData: string, iv: string, tag: string): string {
  const match = FIELD_PREFIX.exec(encryptedData);
  if (!match) return decryptLegacy(encryptedData, iv, tag);
  return openWithDek(fieldKey(findKey(match[1])), match[2], iv, tag);
}

import { Pool } from 'pg';
import dotenv from 'dotenv';

dotenv.config();

let pool: Pool | undefined;

// The pool is created on first use so that importing this module never needs
// a database, and so a missing DATABASE_URL fails closed instead of silently
// falling back to a well-known local credential (see envGuard.ts).
function getPool(): Pool {
  if (!pool) {
    const connectionString = process.env.DATABASE_URL;
    if (!connectionString) {
      throw new Error('DATABASE_URL must be set; refusing to use an unsafe database default');
    }
    pool = new Pool({ connectionString });
    pool.on('error', (err): void => { console.error('pg pool error', err); });
  }
  return pool;
}

export const query = (text: string, params?: any[]) => getPool().query(text, params);

// Must stay first: loads .env and rejects an insecure environment before any
// other module reads configuration at load time (#945).
import "./bootstrapEnv";
import express from "express";
import bodyParser from "body-parser";
import { handleWhatsAppWebhook } from "./webhook";
import { handleDeliveryStatusCallback } from "./statusWebhook";
import { verifyTwilioSignature } from "./twilioSignature";
import { purgeExpiredState } from "./stateManager";

const app = express();
const PORT = process.env.PORT || 3000;

app.use(bodyParser.urlencoded({ extended: false }));
app.use(bodyParser.json());

// Health check endpoint
app.get("/health", (req, res) => {
  res.json({ status: "ok", service: "NeuroWealth WhatsApp Bot Handler" });
});

// WhatsApp Twilio Webhook route
// Only requests signed by Twilio (X-Twilio-Signature) reach the handler.
app.post(
  "/api/whatsapp/webhook",
  verifyTwilioSignature(),
  handleWhatsAppWebhook,
);

// Twilio delivery-status callback for outbound WhatsApp messages
// (queued/sent/delivered/failed/undelivered). Signature validation is
// mandatory here too, before any status is ever persisted.
app.post(
  "/api/whatsapp/status",
  verifyTwilioSignature({
    authToken: process.env.TWILIO_AUTH_TOKEN,
    webhookUrl: process.env.TWILIO_STATUS_CALLBACK_URL,
    skipValidation: process.env.TWILIO_SKIP_SIGNATURE_VALIDATION === "true",
    nodeEnv: process.env.NODE_ENV,
  }),
  handleDeliveryStatusCallback,
);

// Sessions and OTPs live in Postgres now, so idle rows are swept instead of
// being capped in memory. Safe to run on every replica.
const purgeTimer = setInterval(
  () => {
    purgeExpiredState().catch((error: unknown) => {
      console.error(
        "Failed to purge expired WhatsApp state:",
        error instanceof Error ? error.message : error,
      );
    });
  },
  10 * 60 * 1000,
);
purgeTimer.unref();

app.listen(PORT, () => {
  console.log(`🚀 NeuroWealth WhatsApp Bot Handler running on port ${PORT}`);
  console.log(`Webhook URL: http://localhost:${PORT}/api/whatsapp/webhook`);
});

export type IntentType =
  | 'GREETING'
  | 'OTP_CODE'
  | 'DEPOSIT'
  | 'WITHDRAW'
  | 'BALANCE'
  | 'EARNINGS'
  | 'STRATEGY'
  | 'APY'
  | 'UNKNOWN';

export interface ParsedIntent {
  type: IntentType;
  amount?: number;
  withdrawAll?: boolean;
  /**
   * Strategy name as typed by the user (lower-cased). Not guaranteed to be a
   * valid vault strategy; run `validateIntent` before acting on it.
   */
  strategy?: string;
  otpCode?: string;
  rawText: string;
}

const KNOWN_STRATEGIES = ['conservative', 'balanced', 'growth'];

/**
 * Extracts a signed decimal amount, tolerating thousands separators
 * ("1,000.50"). Returns undefined when no amount is present.
 */
function parseAmount(clean: string): number | undefined {
  const match = clean.match(/(-?\d[\d,]*(?:\.\d+)?)/);
  if (!match) return undefined;
  const value = parseFloat(match[1].replace(/,/g, ''));
  return Number.isNaN(value) ? undefined : value;
}

function findKnownStrategy(clean: string): string | undefined {
  return KNOWN_STRATEGIES.find((s) => clean.includes(s));
}

/**
 * Parses user natural language message into structured intent object.
 */
export function parseIntent(message: string): ParsedIntent {
  const clean = message.trim().toLowerCase();
  const rawText = message.trim();

  // Check 6-digit OTP code pattern
  if (/^\d{6}$/.test(clean)) {
    return { type: 'OTP_CODE', otpCode: clean, rawText };
  }

  // Greeting
  if (/^(hi|hello|hey|start|menu|help)$/.test(clean)) {
    return { type: 'GREETING', rawText };
  }

  // Balance query
  // Word-boundary match: matches 'balance' as a whole word but NOT 'balanced'
  // (the 'd' after 'balance' in 'balanced' prevents the trailing \b from matching).
  // Fixes #1167 — previously `clean.includes('balance')` matched the substring
  // inside 'balanced', so 'switch to balanced' was routed to BALANCE before the
  // strategy-change branch at line 76 ever ran.
  if (/\bbalance\b/i.test(clean) || clean.includes('how much do i have') || clean.includes('my funds')) {
    return { type: 'BALANCE', rawText };
  }

  // Earnings query
  if (clean.includes('earnings') || clean.includes('how much have i made') || clean.includes('profit') || clean.includes('yield')) {
    return { type: 'EARNINGS', rawText };
  }

  // APY query
  // Word-boundary match: a bare includes('rate') would also match "strategy".
  if (/\b(apy|rates?|interest rate)\b/.test(clean)) {
    return { type: 'APY', rawText };
  }

  // Strategy change
  if (clean.includes('switch to') || clean.includes('change strategy')) {
    const known = findKnownStrategy(clean);
    if (known) return { type: 'STRATEGY', strategy: known, rawText };
    // Surface the unrecognised name so the validator can reject it explicitly.
    const named = clean.match(/(?:switch to|change strategy(?: to)?)\s+([a-z]+)/);
    return { type: 'STRATEGY', strategy: named ? named[1] : undefined, rawText };
  }

  // Deposit intent
  if (clean.startsWith('deposit') || clean.includes('add money') || clean.includes('put in')) {
    const amount = parseAmount(clean);
    const strategy = findKnownStrategy(clean);
    return { type: 'DEPOSIT', amount, strategy, rawText };
  }

  // Withdraw intent
  if (clean.startsWith('withdraw') || clean.includes('take out') || clean.includes('cash out')) {
    if (clean.includes('all') || clean.includes('everything')) {
      return { type: 'WITHDRAW', withdrawAll: true, rawText };
    }
    const amount = parseAmount(clean);
    return { type: 'WITHDRAW', amount, withdrawAll: false, rawText };
  }

  return { type: 'UNKNOWN', rawText };
}

/**
 * KEK rotation for custodial wallet secrets (#944).
 *
 * `rotateWalletKeys` walks `whatsapp_wallets` in primary-key order and brings
 * every row up to the current KEK (see keyring.ts / docs/WHATSAPP_BOT.md):
 *
 *   - envelope rows wrapped by an older KEK: only the DEK is re-wrapped;
 *   - legacy rows (no envelope): decrypted once, re-encrypted into an envelope.
 *
 * It is idempotent and resumable (rows already on the current version are not
 * selected), safe to run while the bot is serving traffic (each UPDATE is
 * conditional on the row still holding the ciphertext that was read), and
 * never logs key material or secrets.
 */
import { query } from './db';
import { EncryptedSecret, rewrapSecret } from './cryptoUtils';
import { loadKeyring } from './keyring';

export type QueryFn = (text: string, params?: any[]) => Promise<{ rows: any[]; rowCount?: number | null }>;

export interface RotationOptions {
  batchSize?: number;
  /** Verify every row can be re-wrapped but write nothing. */
  dryRun?: boolean;
  queryFn?: QueryFn;
}

export interface RotationResult {
  targetVersion: string;
  rotated: number;
  /** Rows changed by someone else between read and write; picked up by a re-run. */
  skipped: number;
  /** Rows that could not be re-wrapped (e.g. their KEK is missing from the ring). */
  failed: number;
}

interface WalletRow {
  phone_hash: string;
  encrypted_data: string;
  iv: string;
  tag: string;
  wrapped_dek: string | null;
  dek_iv: string | null;
  dek_tag: string | null;
  key_version: string | null;
}

export async function rotateWalletKeys(options: RotationOptions = {}): Promise<RotationResult> {
  const { batchSize = 100, dryRun = false, queryFn = query as QueryFn } = options;
  const targetVersion = loadKeyring().current.version;
  const result: RotationResult = { targetVersion, rotated: 0, skipped: 0, failed: 0 };

  let cursor = '';
  for (;;) {
    const batch = await queryFn(
      `SELECT phone_hash, encrypted_data, iv, tag, wrapped_dek, dek_iv, dek_tag, key_version
         FROM whatsapp_wallets
        WHERE (key_version IS NULL OR key_version <> $1) AND phone_hash > $2
        ORDER BY phone_hash
        LIMIT $3`,
      [targetVersion, cursor, batchSize]
    );
    if (batch.rows.length === 0) break;

    for (const row of batch.rows as WalletRow[]) {
      cursor = row.phone_hash;

      let next;
      try {
        const stored: EncryptedSecret = {
          encryptedData: row.encrypted_data,
          iv: row.iv,
          tag: row.tag,
          wrappedDek: row.wrapped_dek ?? undefined,
          dekIv: row.dek_iv ?? undefined,
          dekTag: row.dek_tag ?? undefined,
          keyVersion: row.key_version ?? undefined,
        };
        next = rewrapSecret(stored);
      } catch {
        result.failed += 1;
        continue;
      }

      if (dryRun) {
        result.rotated += 1;
        continue;
      }

      const updated = await queryFn(
        `UPDATE whatsapp_wallets
            SET encrypted_data = $2, iv = $3, tag = $4,
                wrapped_dek = $5, dek_iv = $6, dek_tag = $7, key_version = $8
          WHERE phone_hash = $1
            AND encrypted_data = $9
            AND key_version IS NOT DISTINCT FROM $10`,
        [
          row.phone_hash,
          next.encryptedData,
          next.iv,
          next.tag,
          next.wrappedDek,
          next.dekIv,
          next.dekTag,
          next.keyVersion,
          row.encrypted_data,
          row.key_version,
        ]
      );
      if ((updated.rowCount ?? 0) > 0) result.rotated += 1;
      else result.skipped += 1;
    }
  }

  return result;
}

/**
 * Key-encryption-key (KEK) ring for custodial wallet secrets (#944).
 *
 * Each wallet secret is encrypted with its own random data-encryption key
 * (DEK); the DEK is wrapped by a KEK taken from this ring. Rotating the KEK
 * therefore only re-wraps small DEKs (see keyRotation.ts) and never exposes
 * or re-encrypts the Stellar secrets themselves.
 *
 *   ENCRYPTION_KEY          current KEK material (>= 32 chars, `openssl rand -hex 32`)
 *   ENCRYPTION_KEY_VERSION  label stored next to every wrapped DEK (default "1")
 *   ENCRYPTION_KEY_RETIRED  `version=key,version=key` of previous KEKs that may
 *                           still wrap not-yet-rotated rows
 *
 * This module is the only place that reads KEK material from the environment,
 * so swapping it for a KMS/HSM client (wrap/unwrap by key id) later touches
 * nothing else.
 */

export const MIN_KEY_LENGTH = 32;
export const DEFAULT_KEY_VERSION = '1';
export const VERSION_PATTERN = /^[A-Za-z0-9_.-]{1,32}$/;

export interface KeyEntry {
  version: string;
  material: string;
}

export interface Keyring {
  current: KeyEntry;
  retired: KeyEntry[];
}

/** Parses `version=key,version=key`. Throws on any malformed or duplicate entry. */
export function parseRetiredKeys(raw: string | undefined): KeyEntry[] {
  if (raw === undefined || raw.trim() === '') return [];

  const entries: KeyEntry[] = [];
  for (const part of raw.split(',')) {
    const trimmed = part.trim();
    const eq = trimmed.indexOf('=');
    if (eq <= 0) {
      throw new Error('ENCRYPTION_KEY_RETIRED entries must look like version=key');
    }
    const version = trimmed.slice(0, eq);
    const material = trimmed.slice(eq + 1);
    if (!VERSION_PATTERN.test(version)) {
      throw new Error(`ENCRYPTION_KEY_RETIRED has an invalid version label "${version}"`);
    }
    if (material.length < MIN_KEY_LENGTH) {
      throw new Error(`ENCRYPTION_KEY_RETIRED key for version "${version}" must be at least ${MIN_KEY_LENGTH} characters`);
    }
    if (entries.some((e) => e.version === version)) {
      throw new Error(`ENCRYPTION_KEY_RETIRED lists version "${version}" more than once`);
    }
    entries.push({ version, material });
  }
  return entries;
}

export function loadKeyring(env: NodeJS.ProcessEnv = process.env): Keyring {
  const material = env.ENCRYPTION_KEY;
  if (!material) {
    throw new Error('ENCRYPTION_KEY must be set; refusing to use an unsafe production default');
  }
  if (material.length < MIN_KEY_LENGTH) {
    throw new Error(`ENCRYPTION_KEY must be at least ${MIN_KEY_LENGTH} characters`);
  }

  const version = env.ENCRYPTION_KEY_VERSION?.trim() || DEFAULT_KEY_VERSION;
  if (!VERSION_PATTERN.test(version)) {
    throw new Error('ENCRYPTION_KEY_VERSION may only contain letters, digits, ".", "_" and "-" (max 32 chars)');
  }

  const retired = parseRetiredKeys(env.ENCRYPTION_KEY_RETIRED);
  if (retired.some((e) => e.version === version)) {
    throw new Error(`ENCRYPTION_KEY_RETIRED must not reuse the current version "${version}"`);
  }

  return { current: { version, material }, retired };
}

import pino from 'pino';
import { query } from './db';
import { hashPhoneNumber, encryptField, decryptField } from './cryptoUtils';
import { boundProviderCallback } from './inputBounds';

const logger = pino({ name: 'whatsapp-message-delivery' });

/**
 * Delivery states Twilio reports for an outbound WhatsApp message, in the
 * order they can legitimately progress. `failed`, `undelivered`, and
 * `delivered` are terminal and share the same rank - once any is reached,
 * the record no longer moves.
 */
export type MessageDeliveryStatus = 'queued' | 'sent' | 'delivered' | 'failed' | 'undelivered';

const STATUS_RANK: Record<MessageDeliveryStatus, number> = {
  queued: 0,
  sent: 1,
  delivered: 2,
  failed: 2,
  undelivered: 2,
};

function isKnownStatus(value: string): value is MessageDeliveryStatus {
  return Object.prototype.hasOwnProperty.call(STATUS_RANK, value);
}

function isTerminalFailure(status: MessageDeliveryStatus): boolean {
  return status === 'failed' || status === 'undelivered';
}

// Matches phone-number-like runs of digits (with optional +, spaces, dashes,
// parens) so provider error text never ends up storing a raw MSISDN.
const PHONE_LIKE_PATTERN = /\+?\d[\d\s().-]{6,}\d/g;

/** Strips phone-number-like substrings from provider error text before it is persisted. */
export function redactErrorMessage(message: string | null | undefined): string | null {
  if (!message) return null;
  return message.replace(PHONE_LIKE_PATTERN, '[redacted]');
}

export interface DeliveryStatusCallback {
  messageSid: string;
  status: string;
  to?: string;
  errorCode?: string;
  errorMessage?: string;
}

export type ApplyResult =
  | { applied: true; created: boolean }
  | { applied: false; reason: 'missing_message_sid' | 'unknown_status' | 'stale_status' | 'rejected_input' };

/**
 * Applies a Twilio delivery-status callback to the reconciliation ledger.
 *
 * Idempotent and order-safe: a callback can only ever move a record's status
 * forward (queued -> sent -> terminal). A duplicate or out-of-order callback
 * (e.g. a delayed "sent" arriving after "delivered" was already recorded) is
 * a no-op rather than regressing a terminal state. The very first callback
 * seen for a MessageSid creates its record - Twilio never gives us a chance
 * to pre-register one, since TwiML-generated replies don't expose their Sid
 * until Twilio assigns it after we've already responded.
 */
export async function applyDeliveryStatus(callback: DeliveryStatusCallback): Promise<ApplyResult> {
  const bounded = boundProviderCallback(callback);
  if (!bounded.ok) {
    logger.warn({ field: bounded.field, reason: bounded.reason }, 'Rejecting delivery status callback outside input bounds');
    return { applied: false, reason: 'rejected_input' };
  }

  const { messageSid, status, to, errorCode, errorMessage } = bounded.value;

  if (!messageSid) {
    logger.warn({ status, to: to ? hashPhoneNumber(to) : to }, 'Ignoring delivery status callback with no MessageSid');
    return { applied: false, reason: 'missing_message_sid' };
  }

  if (!isKnownStatus(status)) {
    logger.warn({ messageSid, status }, 'Ignoring delivery status callback with an unrecognized status');
    return { applied: false, reason: 'unknown_status' };
  }

  const redactedError = redactErrorMessage(errorMessage);
  const existing = await query(
    'SELECT status FROM whatsapp_message_deliveries WHERE message_sid = $1',
    [messageSid]
  );

  if (existing.rows.length === 0) {
    const phoneHash = to ? hashPhoneNumber(to) : null;
    const encryptedTo = to ? encryptField(to) : null;

    const inserted = await query(
      `INSERT INTO whatsapp_message_deliveries
         (message_sid, phone_hash, to_encrypted, to_iv, to_tag, status, error_code, error_reason, retry_count, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 0, NOW(), NOW())
       ON CONFLICT (message_sid) DO NOTHING`,
      [
        messageSid,
        phoneHash,
        encryptedTo?.encryptedData ?? null,
        encryptedTo?.iv ?? null,
        encryptedTo?.tag ?? null,
        status,
        errorCode ?? null,
        redactedError,
      ]
    );

    if ((inserted.rowCount ?? 0) > 0) {
      logger.info({ messageSid, status }, 'Recorded new outbound message delivery status');
      return { applied: true, created: true };
    }
  }

  const currentStatus = existing.rows[0]?.status as MessageDeliveryStatus | undefined;
  if (currentStatus !== undefined && STATUS_RANK[status] <= STATUS_RANK[currentStatus]) {
    logger.info(
      { messageSid, status, currentStatus },
      'Ignoring duplicate or out-of-order delivery status callback; current state is already as advanced'
    );
    return { applied: false, reason: 'stale_status' };
  }

  const updated = await query(
    `UPDATE whatsapp_message_deliveries
       SET status = $2, error_code = $3, error_reason = $4, updated_at = NOW()
     WHERE message_sid = $1
       AND CASE status
         WHEN 'queued' THEN 0
         WHEN 'sent' THEN 1
         WHEN 'delivered' THEN 2
         WHEN 'failed' THEN 2
         WHEN 'undelivered' THEN 2
         ELSE -1
       END < $5`,
    [messageSid, status, errorCode ?? null, redactedError, STATUS_RANK[status]]
  );

  if ((updated.rowCount ?? 0) === 0) {
    return { applied: false, reason: 'stale_status' };
  }

  logger.info({ messageSid, status, previousStatus: currentStatus }, 'Updated outbound message delivery status');
  return { applied: true, created: false };
}

const MAX_DELIVERY_RETRIES = 3;

export interface RetryOutcome {
  retried: boolean;
  escalated: boolean;
}

/**
 * Bounded retry for a terminally-failed delivery. The caller supplies the
 * actual resend action (e.g. a Twilio REST send) so this module stays
 * transport-agnostic and testable. After `MAX_DELIVERY_RETRIES` attempts we
 * stop retrying and escalate instead of retrying forever.
 */
export async function retryFailedDelivery(
  messageSid: string,
  resend: (to: string) => Promise<void>,
  onEscalate: (messageSid: string) => void = (sid) =>
    logger.error({ messageSid: sid }, 'Delivery failure escalated after exhausting retries')
): Promise<RetryOutcome> {
  const existing = await query(
    'SELECT status, to_encrypted, to_iv, to_tag, retry_count FROM whatsapp_message_deliveries WHERE message_sid = $1',
    [messageSid]
  );

  if (existing.rows.length === 0) {
    return { retried: false, escalated: false };
  }

  const row = existing.rows[0];
  const status = row.status as MessageDeliveryStatus;
  const retryCount = Number(row.retry_count) || 0;

  if (!isTerminalFailure(status)) {
    return { retried: false, escalated: false };
  }

  if (retryCount >= MAX_DELIVERY_RETRIES || !row.to_encrypted) {
    await query(
      'UPDATE whatsapp_message_deliveries SET escalated_at = NOW() WHERE message_sid = $1 AND escalated_at IS NULL',
      [messageSid]
    );
    onEscalate(messageSid);
    return { retried: false, escalated: true };
  }

  const to = decryptField(row.to_encrypted, row.to_iv, row.to_tag);

  await query(
    'UPDATE whatsapp_message_deliveries SET retry_count = retry_count + 1, updated_at = NOW() WHERE message_sid = $1',
    [messageSid]
  );

  await resend(to);

  return { retried: true, escalated: false };
}

import twilio from 'twilio';

export async function deliverOTP(phoneNumber: string, code: string): Promise<void> {
  const accountSid = process.env.TWILIO_ACCOUNT_SID;
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  const fromNumber = process.env.TWILIO_SMS_FROM;

  if (!accountSid || !authToken || !fromNumber) {
    throw new Error('OTP SMS delivery is not configured');
  }

  const client = twilio(accountSid, authToken);
