    from: fromNumber,
    to: phoneNumber,
  });
}

import crypto from 'crypto';
import { getStateStore } from './stateStore';

const OTP_TTL_MS = parseInt(process.env.WHATSAPP_OTP_TTL_MS || '300000', 10); // 5 minutes default
const MAX_ATTEMPTS = parseInt(process.env.WHATSAPP_OTP_MAX_ATTEMPTS || '3', 10);

// Challenges are persisted in Postgres (see stateStore.ts) so they survive
// restarts and are shared by every replica. Only a hash is stored, bound to
// the phone hash so identical codes for different users never collide.
function hashOTP(phoneHash: string, code: string): string {
  return crypto.createHash('sha256').update(`${phoneHash}:${code}`).digest('hex');
}

function isOTPMatch(phoneHash: string, storedHash: string, inputCode: string): boolean {
  const inputHash = hashOTP(phoneHash, inputCode.trim());
  const stored = Buffer.from(storedHash, 'hex');
  const input = Buffer.from(inputHash, 'hex');

  return stored.length === input.length && crypto.timingSafeEqual(stored, input);
}

/**
 * Generates a 6-digit numeric OTP that expires after 5 minutes.
 */
export async function generateOTP(phoneHash: string): Promise<string> {
  const code = crypto.randomInt(100000, 999999).toString();
  await getStateStore().putOtp(phoneHash, hashOTP(phoneHash, code), Date.now() + OTP_TTL_MS);
  return code;
}

/**
 * Verifies an OTP code for a user.
 * Enforces 5-minute expiration and max attempt limits. Each call counts as an
 * attempt atomically in the database, so replicas cannot exceed the limit by
 * guessing in parallel, and a correct code can be redeemed only once.
 */
export async function verifyOTP(phoneHash: string, inputCode: string): Promise<{ success: boolean; message: string; shouldResetSession: boolean }> {
  const store = getStateStore();
  const attempt = await store.attemptOtp(phoneHash, Date.now(), MAX_ATTEMPTS);

  switch (attempt.kind) {
    case 'none':
      return { success: false, message: 'No OTP request found. Please send "hi" to request a new code.', shouldResetSession: false };
    case 'expired':
      return { success: false, message: 'OTP has expired (valid for 5 minutes). Please send "hi" to request a new code.', shouldResetSession: true };
    case 'locked':
      return { success: false, message: 'Too many invalid attempts. Please send "hi" to request a new OTP code.', shouldResetSession: true };
  }

  if (!isOTPMatch(phoneHash, attempt.codeHash, inputCode)) {
    return { success: false, message: `Invalid OTP code. ${Math.max(MAX_ATTEMPTS - attempt.attempts, 0)} attempts remaining.`, shouldResetSession: false };
  }

  // Verification successful: consume the code. Losing this race means another
  // replica already redeemed it.
  if (!(await store.consumeOtp(phoneHash, attempt.codeHash))) {
    return { success: false, message: 'No OTP request found. Please send "hi" to request a new code.', shouldResetSession: false };
  }
  return { success: true, message: 'OTP verified successfully!', shouldResetSession: false };
}

import twilio from "twilio";
import pino from "pino";

const logger = pino({ name: "whatsapp-sms" });

/**
 * Thin wrapper around the Twilio REST client, exposed as a mutable object so
 * tests can monkey-patch `send` instead of hitting the real Twilio API
 * (mirrors the `server`/`pool` monkey-patch pattern used in agent tests).
 */
export const smsClient = {
  async send(toNumber: string, body: string): Promise<string> {
    const accountSid = process.env.TWILIO_ACCOUNT_SID;
    const authToken = process.env.TWILIO_AUTH_TOKEN;
    const from = process.env.TWILIO_SMS_FROM_NUMBER;

    if (!accountSid || !authToken || !from) {
      throw new Error(
        "Twilio SMS is not configured (TWILIO_ACCOUNT_SID/TWILIO_AUTH_TOKEN/TWILIO_SMS_FROM_NUMBER)",
      );
    }

    const client = twilio(accountSid, authToken);
    const message = await client.messages.create({
      to: stripWhatsAppPrefix(toNumber),
      from,
      body,
    });
    return message.sid;
  },
};

function stripWhatsAppPrefix(number: string): string {
  return number.startsWith("whatsapp:")
    ? number.slice("whatsapp:".length)
    : number;
}

/**
 * Delivers an OTP code to the user's phone via SMS. The code must never be
 * echoed back in the WhatsApp chat reply (#942), so this is the only place
 * the plaintext code is transmitted to the user.
 */
export async function sendOtpSms(
  toNumber: string,
  code: string,
): Promise<string> {
  try {
    const messageSid = await smsClient.send(
      toNumber,
      `Your NeuroWealth verification code is ${code}. It expires in 5 minutes.`,
    );
    return messageSid;
  } catch (error) {
    logger.error(
      { error: error instanceof Error ? error.message : error },
      "Failed to send OTP SMS",
    );
    throw error;
  }
}

import { getStateStore } from './stateStore';

export enum UserState {
  UNVERIFIED = 'UNVERIFIED',
  AWAITING_OTP = 'AWAITING_OTP',
  VERIFIED = 'VERIFIED'
}

export interface ConversationSession {
  state: UserState;
  lastMessageTime: number;
  messageCount: number;
  rateLimitWindowStart: number;
}

const SESSION_TIMEOUT_MS = parseInt(process.env.WHATSAPP_SESSION_TIMEOUT_MS || '900000', 10); // 15 minutes default
const RATE_LIMIT_MAX_MESSAGES = parseInt(process.env.WHATSAPP_RATE_LIMIT_MAX_MESSAGES || '10', 10);
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.WHATSAPP_RATE_LIMIT_WINDOW_MS || '60000', 10); // 1 minute default

// Sessions are persisted in Postgres (see stateStore.ts) so a restart or a
// request landing on another replica sees the same conversation state.

/**
 * Retrieves session for phone hash, resetting if timed out.
 */
export async function getSession(phoneHash: string): Promise<ConversationSession> {
  const session = await getStateStore().touchSession(phoneHash, Date.now(), SESSION_TIMEOUT_MS);
  return { ...session, state: session.state as UserState };
}

/**
 * Updates user state in session.
 */
export async function updateState(phoneHash: string, newState: UserState): Promise<void> {
  await getStateStore().setSessionState(phoneHash, newState, Date.now());
}

/**
 * Enforces per-phone rate limiting.
 */
export async function checkRateLimit(phoneHash: string): Promise<boolean> {
  const now = Date.now();
  // Touching first applies the inactivity reset, as before.
  await getStateStore().touchSession(phoneHash, now, SESSION_TIMEOUT_MS);
  const count = await getStateStore().bumpMessageCount(phoneHash, now, RATE_LIMIT_WINDOW_MS);
  return count <= RATE_LIMIT_MAX_MESSAGES;
}

/**
 * Deletes sessions idle past the timeout and expired OTP challenges.
 * Replaces the old in-memory size cap; safe to run from every replica.
 */
export async function purgeExpiredState(): Promise<void> {
  await getStateStore().purgeExpired(Date.now(), SESSION_TIMEOUT_MS);
}

import { Request, Response } from "express";
import pino from "pino";
import {
  applyDeliveryStatus,
  retryFailedDelivery,
} from "./messageDeliveryService";
import { boundProviderCallback } from "./inputBounds";
import { smsClient } from "./smsService";

const logger = pino({ name: "whatsapp-status-webhook" });

/**
 * Twilio calls this URL asynchronously as an outbound WhatsApp message moves
 * through queued -> sent -> delivered (or failed / undelivered). We always
 * acknowledge with 200 so Twilio does not retry-storm us - even a callback
 * for an identifier we can't reconcile is logged and dropped, not failed.
 */
export async function handleDeliveryStatusCallback(
  req: Request,
  res: Response,
): Promise<void> {
  const body = req.body ?? {};
  const messageSid = body.MessageSid || body.SmsSid || "";
  const status =
    typeof body.MessageStatus === "string"
      ? body.MessageStatus
      : (body.MessageStatus ?? "");
  const bounded = boundProviderCallback({
    messageSid,
    status,
    to: body.To,
    errorCode: body.ErrorCode,
    errorMessage: body.ErrorMessage,
  });

  if (!bounded.ok) {
    logger.warn(
      { field: bounded.field, reason: bounded.reason },
      "Dropping provider callback outside input bounds",
    );
    res.status(200).send();
    return;
  }

  try {
    const result = await applyDeliveryStatus({
      messageSid: bounded.value.messageSid,
      status: bounded.value.status.toLowerCase(),
      to: bounded.value.to,
      errorCode: bounded.value.errorCode,
      errorMessage: bounded.value.errorMessage,
    });

    // Trigger retry/escalation on terminal failure
    if (
      result.applied &&
      (bounded.value.status.toLowerCase() === "failed" ||
        bounded.value.status.toLowerCase() === "undelivered")
    ) {
      await retryFailedDelivery(
        bounded.value.messageSid,
        async (to) => {
          // Resend SMS without the OTP code (code is device-only per #942)
          // The user's device has the original code, so this is just a reattempt to deliver
          await smsClient.send(
            to,
            "Your NeuroWealth verification code was not delivered. Please check your SMS or request a new code in the WhatsApp chat.",
          );
        },
        (sid) => {
          logger.error(
            { messageSid: sid },
            "OTP delivery failure escalated after exhausting retries",
          );
        },
      );
    }
  } catch (error) {
    logger.error(
      { error, messageSid: bounded.value.messageSid },
      "Failed to persist delivery status callback",
    );
  }

  res.status(200).send();
}

/**
 * Shared test bootstrap for WhatsApp unit tests.
 *
 * Sets dummy environment variables when unset and replaces `./db` in the
 * CommonJS require cache with an in-memory `whatsapp_wallets` store so tests
 * run in a clean checkout without a live PostgreSQL database or deployment
 * secrets.
 */

process.env.ENCRYPTION_KEY ??= 'test-encryption-key-at-least-32-chars!!';
process.env.PHONE_HASH_SALT ??= 'test-phone-salt';
process.env.SOROBAN_RPC_URL ??= 'https://soroban-testnet.stellar.org';
process.env.VAULT_CONTRACT_ID ??= 'CTEST_VAULT_CONTRACT_ID';

interface WalletRow {
  phone_hash: string;
  public_key: string;
  encrypted_data: string;
  iv: string;
  tag: string;
  created_at: string;
  wrapped_dek: string | null;
  dek_iv: string | null;
  dek_tag: string | null;
  key_version: string | null;
}

const wallets = new Map<string, WalletRow>();
const deliveries = new Map<string, { status: string }>();

async function inMemoryQuery(sql: string, params: unknown[] = []): Promise<{ rows: unknown[]; rowCount?: number }> {
  const normalized = sql.replace(/\s+/g, ' ').trim().toUpperCase();

  if (normalized.startsWith('INSERT INTO WHATSAPP_WALLETS')) {
    const [
      phoneHash,
      publicKey,
      encryptedData,
      iv,
      tag,
      createdAtMs,
      wrappedDek,
      dekIv,
      dekTag,
      keyVersion,
    ] = params as [
      string,
      string,
      string,
      string,
      string,
      number,
      string | undefined,
      string | undefined,
      string | undefined,
      string | undefined,
    ];

    if (wallets.has(phoneHash)) {
      return { rows: [] };
    }

    const row: WalletRow = {
      phone_hash: phoneHash,
      public_key: publicKey,
      encrypted_data: encryptedData,
      iv,
      tag,
      created_at: new Date(typeof createdAtMs === 'number' ? createdAtMs : Date.now()).toISOString(),
      wrapped_dek: wrappedDek ?? null,
      dek_iv: dekIv ?? null,
      dek_tag: dekTag ?? null,
      key_version: keyVersion ?? null,
    };
    wallets.set(phoneHash, row);
    return { rows: [row] };
  }

  if (normalized.startsWith('SELECT * FROM WHATSAPP_WALLETS')) {
    const [phoneHash] = params as [string];
    const row = wallets.get(phoneHash);
    return { rows: row ? [row] : [] };
  }

  if (normalized.startsWith('SELECT STATUS FROM WHATSAPP_MESSAGE_DELIVERIES')) {
    const [messageSid] = params as [string];
    const row = deliveries.get(messageSid);
    return { rows: row ? [row] : [] };
  }

  if (normalized.startsWith('INSERT INTO WHATSAPP_MESSAGE_DELIVERIES')) {
    const [messageSid, , , , , status] = params as [string, unknown, unknown, unknown, unknown, string];
    if (deliveries.has(messageSid)) {
      return { rows: [], rowCount: 0 };
    }
    deliveries.set(messageSid, { status });
    return { rows: [], rowCount: 1 };
  }

  throw new Error(`inMemoryQuery: unrecognized SQL: ${sql}`);
}

