/**
 * Rejects any request whose `X-Twilio-Signature` header is missing or does not
 * match the HMAC-SHA1 of the URL + POST params signed with TWILIO_AUTH_TOKEN.
 * Fails closed: without an auth token every request is refused, unless
 * validation is explicitly skipped outside production.
 */
export function verifyTwilioSignature(
  options: TwilioSignatureOptions = optionsFromEnv(),
): RequestHandler {
  const { authToken, webhookUrl, skipValidation, nodeEnv } = options;
  const bypass = skipValidation === true && nodeEnv !== 'production';

  if (bypass) {
    console.warn('⚠️ Twilio signature validation is DISABLED (TWILIO_SKIP_SIGNATURE_VALIDATION=true). Never use this in production.');
  } else if (!authToken) {
    console.error('TWILIO_AUTH_TOKEN is not set; all WhatsApp webhook requests will be rejected.');
  }

  return (req: Request, res: Response, next: NextFunction): void => {
    if (bypass) {
      next();
      return;
    }

    if (!authToken) {
      res.status(500).send('Webhook signature validation is not configured');
      return;
    }

    const isHttps = req.secure || req.headers['x-forwarded-proto'] === 'https' || req.protocol === 'https';
    if (nodeEnv === 'production' && !isHttps) {
      res.status(403).send('HTTPS required in production');
      return;
    }

    const signature = req.get('X-Twilio-Signature');
    if (!signature) {
      res.status(403).send('Missing Twilio signature');
      return;
    }

    const url = webhookUrl || requestUrl(req);
    const params = req.body && typeof req.body === 'object' ? req.body : {};

    if (!twilio.validateRequest(authToken, signature, url, params)) {
      res.status(403).send('Invalid Twilio signature');
      return;
    }

    next();
  };
}

import { Keypair } from '@stellar/stellar-sdk';
import { VaultClient, VaultError, VaultErrorCode } from '@neurowealth/vault-client';
import { getWallet, getDecryptedSecretKey } from './walletService';
import { INPUT_LIMITS, SAFE_OVERSIZE_REPLY, boundText } from './inputBounds';
import { isValidStrategy, type Strategy } from './contractLimits';

function rejectUnusableAddress(publicKey: string): string | null {
  const checked = boundText(publicKey, INPUT_LIMITS.address);
  return checked.ok ? null : SAFE_OVERSIZE_REPLY;
}

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`${name} must be set; refusing to use an unsafe vault contract default`);
  }
  return value;
}

/** USDC has 7 decimal places on this vault; see contractLimits.ts's own USDC_DECIMALS. */
const USDC_DECIMALS = 7;
const STROOPS_PER_USDC = 10 ** USDC_DECIMALS;

function toStroops(usdcAmount: number): bigint {
  return BigInt(Math.round(usdcAmount * STROOPS_PER_USDC));
}

function fromStroops(stroops: bigint): number {
  return Number(stroops) / STROOPS_PER_USDC;
}

function vaultClient(): VaultClient {
  return new VaultClient({
    contractId: requireEnv('VAULT_CONTRACT_ID'),
    rpcUrl: requireEnv('SOROBAN_RPC_URL'),
  });
}

function toStrategySymbol(strategy: string): Strategy | null {
  const symbol = strategy.trim().toLowerCase();
  return isValidStrategy(symbol) ? symbol : null;
}

/**
 * Submit `set_user_strategy` and refuse to report success without the
 * transaction hash the vault client returns (#1107).
 */
async function applyUserStrategy(
  client: VaultClient,
  signer: Keypair,
  publicKey: string,
  strategy: string,
): Promise<{ ok: true; txHash: string; symbol: Strategy } | { ok: false; message: string }> {
  const symbol = toStrategySymbol(strategy);
  if (!symbol) {
    return { ok: false, message: 'Invalid strategy specified on-chain transaction failed.' };
  }
  const result = await client.set_user_strategy(signer, publicKey, symbol);
  if (!result.hash) {
    throw new Error('set_user_strategy: transaction did not return a hash');
  }
  return { ok: true, txHash: result.hash, symbol };
}

/**
 * Maps a VaultError raised by a deposit/withdraw invocation to a message
 * safe to show a WhatsApp user. Falls back to a generic message for any
 * code not explicitly handled here, so a new or unmapped contract error
 * never leaks a raw contract code or stack trace into chat (#1001).
 */
function friendlyVaultErrorMessage(err: unknown): string {
  if (err instanceof VaultError) {
    switch (err.code) {
      case VaultErrorCode.Paused:
        return 'The vault is temporarily paused for maintenance. Please try again shortly.';
      case VaultErrorCode.AmountMustBePositive:
        return 'The amount must be greater than 0.';
      case VaultErrorCode.BelowMinimumDeposit:
        return 'That deposit is below the minimum the vault currently accepts.';
      case VaultErrorCode.MaximumDepositExceeded:
        return 'That deposit is above the maximum the vault currently accepts in one transaction.';
      case VaultErrorCode.ExceedsUserDepositCap:
        return 'That would put you over your per-user deposit cap.';
      case VaultErrorCode.ExceedsTvlCap:
        return 'The vault is at its total deposit cap right now. Please try again later.';
      case VaultErrorCode.InsufficientShares:
      case VaultErrorCode.InsufficientSharesForAmount:
      case VaultErrorCode.NoSharesToWithdraw:
        return "You don't have enough in your vault position to withdraw that amount.";
      case VaultErrorCode.InsufficientLiquidity:
      case VaultErrorCode.NoLiquidityAvailable:
      case VaultErrorCode.NoAssetsToWithdraw:
        return 'The vault does not have enough liquid funds to process that withdrawal right now. Please try again shortly.';
      default:
        return 'The transaction was rejected by the vault contract. Please try again, or contact support if this continues.';
    }
  }
  return 'The transaction could not be submitted. Please try again shortly.';
}

interface LoadedSigner {
  publicKey: string;
  signer: Keypair;
}

/** Loads the caller's wallet and decrypted signing key, or an error reply if either step fails. */
async function loadSigner(phoneHash: string): Promise<LoadedSigner | { error: string }> {
  const wallet = await getWallet(phoneHash);
  if (!wallet) {
    return { error: 'Wallet not initialized.' };
  }
  const addressError = rejectUnusableAddress(wallet.publicKey);
  if (addressError) {
    return { error: addressError };
  }
  const secret = await getDecryptedSecretKey(phoneHash);
  if (!secret) {
    return { error: 'Wallet not initialized.' };
  }
  return { publicKey: wallet.publicKey, signer: Keypair.fromSecret(secret) };
}

export interface UserPortfolio {
  balance: number;
  usdEquivalent: number;
  strategy: string;
  apy: number;
  dailyEarnings: number;
}

const STRATEGY_MAP: Record<string, string> = {
  conservative: 'Conservative',
  balanced: 'Balanced',
  growth: 'Growth',
};

/**
 * Reads vault state and portfolio details for a verified WhatsApp user.
 */
export async function getPortfolio(phoneHash: string): Promise<UserPortfolio> {
  const wallet = await getWallet(phoneHash);
  if (!wallet) {
    throw new Error('Wallet not found');
  }

  try {
    const client = vaultClient();
    const sourcePublicKey = wallet.publicKey;
    const [balanceRaw, rawStrategy, userApyRaw] = await Promise.all([
      client.get_balance(wallet.publicKey, sourcePublicKey),
      client.get_user_strategy(wallet.publicKey, sourcePublicKey),
      client.get_user_apy(wallet.publicKey, sourcePublicKey).catch(() => 0n),
    ]);

    const balance = fromStroops(balanceRaw);
    const strategy = STRATEGY_MAP[String(rawStrategy)] || 'Balanced';
    const apy = Number((Number(userApyRaw) / 100).toFixed(2));

    // get_balance already returns the user's USDC asset value (1 USDC = $1.00 USD).
    const usdEquivalent = Number(balance.toFixed(2));
    const dailyEarnings = balance > 0 && apy > 0 ? (balance * (apy / 100)) / 365 : 0;

    return {
      balance,
      usdEquivalent,
      strategy,
      apy,
      dailyEarnings: Number(dailyEarnings.toFixed(4))
    };
  } catch (err) {
    console.warn('Failed to fetch vault state from Soroban RPC:', err);
    return {
      balance: 0,
      usdEquivalent: 0,
      strategy: 'Balanced',
      apy: 0,
      dailyEarnings: 0
    };
  }
}

/**
 * Handles a deposit for a verified WhatsApp user: builds, signs with the
 * decrypted custodial key, submits and polls a real `deposit` invocation on
 * the vault contract via @neurowealth/vault-client (#1001). No success
 * reply is ever sent without on-chain confirmation; a mapped, non-leaking
 * message is sent on failure.
 */
export async function handleDeposit(
  phoneHash: string,
  amount: number,
  strategy?: string
): Promise<{ success: boolean; txHash: string; message: string }> {
  const loaded = await loadSigner(phoneHash);
  if ('error' in loaded) {
    return { success: false, txHash: '', message: loaded.error };
  }

  const selectedStrategy = strategy || 'Balanced';

  try {
    const client = vaultClient();
    // The deposit invocation has no strategy argument. Persist the choice
    // with set_user_strategy before claiming the deposit succeeded (#1107).
    if (strategy) {
      const applied = await applyUserStrategy(client, loaded.signer, loaded.publicKey, strategy);
      if (!applied.ok) {
        return { success: false, txHash: '', message: applied.message };
      }
    }
    const result = await client.deposit(loaded.signer, loaded.publicKey, toStroops(amount));
    if (!result.hash) {
      throw new Error('deposit: transaction did not return a hash');
    }

    return {
      success: true,
      txHash: result.hash,
      message: `Deposited ${amount} USDC into your ${selectedStrategy} strategy.\nTransaction Hash: ${result.hash.substring(0, 10)}...\nConfirmed on Stellar.`
    };
  } catch (err) {
    console.warn('Deposit failed:', err);
    return { success: false, txHash: '', message: friendlyVaultErrorMessage(err) };
  }
}

/**
 * Handles a withdrawal for a verified WhatsApp user: builds, signs with the
 * decrypted custodial key, submits and polls a real `withdraw` or
 * `withdraw_all` invocation on the vault contract via
 * @neurowealth/vault-client (#1001). No success reply is ever sent without
 * on-chain confirmation; a mapped, non-leaking message is sent on failure.
 */
export async function handleWithdraw(
  phoneHash: string,
  amount?: number,
  withdrawAll?: boolean
): Promise<{ success: boolean; txHash: string; message: string }> {
  const loaded = await loadSigner(phoneHash);
  if ('error' in loaded) {
    return { success: false, txHash: '', message: loaded.error };
  }

  const withdrawAmountText = withdrawAll ? 'all funds' : `${amount} USDC`;

  try {
    const client = vaultClient();
    const result = withdrawAll
      ? await client.withdraw_all(loaded.signer, loaded.publicKey)
      : await client.withdraw(loaded.signer, loaded.publicKey, toStroops(amount as number));
    if (!result.hash) {
      throw new Error('withdraw: transaction did not return a hash');
    }

    return {
      success: true,
      txHash: result.hash,
      message: `Withdrew ${withdrawAmountText} from vault contract.\nTransaction Hash: ${result.hash.substring(0, 10)}...\nFunds sent directly to your wallet.`
    };
  } catch (err) {
    console.warn('Withdraw failed:', err);
    return { success: false, txHash: '', message: friendlyVaultErrorMessage(err) };
  }
}

/**
 * Updates the user's strategy on the vault contract via `set_user_strategy`.
 * Success is reported only after the client returns a transaction hash (#1107).
 */
export async function handleStrategyUpdate(
  phoneHash: string,
  strategy: string
): Promise<{ success: boolean; txHash: string; message: string }> {
  const loaded = await loadSigner(phoneHash);
  if ('error' in loaded) {
    return { success: false, txHash: '', message: loaded.error };
  }

  try {
    const client = vaultClient();
    const applied = await applyUserStrategy(client, loaded.signer, loaded.publicKey, strategy);
    if (!applied.ok) {
      return { success: false, txHash: '', message: applied.message };
    }

    return {
      success: true,
      txHash: applied.txHash,
      message: `Strategy updated to ${strategy.toUpperCase()}. The AI agent will rebalance your portfolio on the next scheduled run.\nTransaction Hash: ${applied.txHash.substring(0, 10)}...`
    };
  } catch (err) {
    console.warn('Strategy update failed:', err);
    return { success: false, txHash: '', message: friendlyVaultErrorMessage(err) };
  }
}

import { Keypair } from '@stellar/stellar-sdk';
import { encryptSecretKey, decryptSecretKey, EncryptedSecret } from './cryptoUtils';
import { query } from './db';

export interface UserWallet {
  publicKey: string;
  encryptedSecret: EncryptedSecret;
  createdAt: number;
}

export interface CustodialWalletResult {
  wallet: UserWallet;
  /** False when phoneHash already had a wallet; the fresh keypair generated
   * this call was discarded and the pre-existing stored wallet is returned
   * instead. */
  isNew: boolean;
}

/**
 * Returns the custodial Stellar wallet for a verified user, creating one if
 * none exists yet.
 *
 * A fresh keypair is always generated up front, but `INSERT ... ON CONFLICT
 * DO NOTHING RETURNING *` means the generated keypair is only ever persisted
 * (and only ever returned) when no row already existed for phoneHash. For a
 * returning user - e.g. a session that timed out and re-verified - the
 * insert is a no-op and the pre-existing stored wallet is read back via
 * getWallet instead, so the public key returned always matches a secret key
 * that was actually saved (#1000). The fresh keypair generated for a no-op
 * insert is discarded in memory and never shown to the caller.
 */
export async function createCustodialWallet(phoneHash: string): Promise<CustodialWalletResult> {
  const pair = Keypair.random();
  const publicKey = pair.publicKey();
  const secretKey = pair.secret();

  const encryptedSecret = encryptSecretKey(secretKey);
  const createdAt = Date.now();

  const result = await query(
    `INSERT INTO whatsapp_wallets
       (phone_hash, public_key, encrypted_data, iv, tag, created_at, wrapped_dek, dek_iv, dek_tag, key_version)
     VALUES ($1, $2, $3, $4, $5, to_timestamp($6 / 1000.0), $7, $8, $9, $10)
     ON CONFLICT (phone_hash) DO NOTHING
     RETURNING public_key, encrypted_data, iv, tag, created_at, wrapped_dek, dek_iv, dek_tag, key_version`,
    [
      phoneHash,
      publicKey,
      encryptedSecret.encryptedData,
      encryptedSecret.iv,
      encryptedSecret.tag,
      createdAt,
      encryptedSecret.wrappedDek,
      encryptedSecret.dekIv,
      encryptedSecret.dekTag,
      encryptedSecret.keyVersion
    ]
  );

  if (result.rows.length > 0) {
    return {
      wallet: { publicKey, encryptedSecret, createdAt },
      isNew: true
    };
  }

  const existing = await getWallet(phoneHash);
  if (!existing) {
    // The insert found a conflicting row (so it did not insert), but that
    // row is now gone - a concurrent delete between the two queries.
    // Extremely unlikely, but surfacing it as an error is safer than
    // silently handing back the discarded fresh keypair as if it were saved.
    throw new Error(`createCustodialWallet: no wallet found for phoneHash after a no-op insert`);
  }
  return { wallet: existing, isNew: false };
}

/**
 * Retrieves a user's wallet info (public key and encrypted secret).
 */
export async function getWallet(phoneHash: string): Promise<UserWallet | undefined> {
  const res = await query('SELECT * FROM whatsapp_wallets WHERE phone_hash = $1', [phoneHash]);
  if (res.rows.length === 0) return undefined;

  const row = res.rows[0];
  return {
    publicKey: row.public_key,
    encryptedSecret: {
      encryptedData: row.encrypted_data,
      iv: row.iv,
      tag: row.tag,
      // NULL for rows written before envelope encryption (#944).
      wrappedDek: row.wrapped_dek ?? undefined,
      dekIv: row.dek_iv ?? undefined,
      dekTag: row.dek_tag ?? undefined,
      keyVersion: row.key_version ?? undefined
    },
    createdAt: new Date(row.created_at).getTime()
  };
}

/**
 * Decrypts secret key for transaction execution. Key is never saved in plaintext or output to chat.
 */
export async function getDecryptedSecretKey(phoneHash: string): Promise<string | null> {
  const wallet = await getWallet(phoneHash);
  if (!wallet) return null;

  return decryptSecretKey(
    wallet.encryptedSecret.encryptedData,
    wallet.encryptedSecret.iv,
    wallet.encryptedSecret.tag,
    wallet.encryptedSecret
  );
}

import { Request, Response } from "express";
import twilio from "twilio";
import pino from "pino";
import { hashPhoneNumber } from "./cryptoUtils";
import { runExclusive } from "./commandLock";
import {
  deriveIdempotencyKey,
  getIdempotencyStore,
  IdempotencyStore,
  isTransientError,
  LeaseLostError,
  RetryableWebhookError,
  SideEffectGuard,
  WEBHOOK_LEASE_MS,
} from "./webhookIdempotency";

const logger = pino({ name: "whatsapp-webhook" });

import {
  getSession,
  updateState,
  checkRateLimit,
  UserState,
} from "./stateManager";
import { generateOTP, verifyOTP } from "./otpService";
import { sendOtpSms } from "./smsService";
import { applyDeliveryStatus } from "./messageDeliveryService";
import { createCustodialWallet, getWallet } from "./walletService";
import { parseIntent } from "./intentParser";
import { validateIntent } from "./contractLimits";
import {
  getPortfolio,
  handleDeposit,
  handleWithdraw,
  handleStrategyUpdate,
} from "./vaultRouter";
import {
  INPUT_LIMITS,
  SAFE_MALFORMED_REPLY,
  SAFE_OVERSIZE_REPLY,
  SAFE_STRATEGY_REPLY,
  boundOutbound,
  boundText,
} from "./inputBounds";

function reply(
  twiml: { message: (body: string) => unknown },
  text: string,
): void {
  twiml.message(boundOutbound(text));
}

function rejectInbound(
  res: Response,
  reason: "oversize" | "malformed" | "type",
): void {
  const twiml = new MessagingResponse();
  reply(
    twiml,
    reason === "oversize" ? SAFE_OVERSIZE_REPLY : SAFE_MALFORMED_REPLY,
  );
  res.type("text/xml").send(twiml.toString());
}

const MessagingResponse = twilio.twiml.MessagingResponse;

/** Acknowledges a webhook without sending any reply message to the user. */
const EMPTY_TWIML =
  '<?xml version="1.0" encoding="UTF-8"?><Response></Response>';

/**
 * Main Webhook Handler for WhatsApp Messages (Twilio HTTP POST)
 */
export async function handleWhatsAppWebhook(
  req: Request,
  res: Response,
): Promise<void> {
  const fromNumber = req.body?.From;
  const messageBody = req.body?.Body;

  if (fromNumber === undefined || fromNumber === null || fromNumber === "") {
    res.status(400).send("Missing sender phone number");
    return;
  }

  const fromCheck = boundText(fromNumber, INPUT_LIMITS.address);
  if (!fromCheck.ok) {
    rejectInbound(res, fromCheck.reason);
    return;
  }

  const bodyCheck = boundText(messageBody ?? "", INPUT_LIMITS.inboundBody);
  if (!bodyCheck.ok) {
    rejectInbound(res, bodyCheck.reason);
    return;
  }

  const commandCheck = boundText(
    bodyCheck.value.trim(),
    INPUT_LIMITS.commandText,
  );
  if (!commandCheck.ok) {
    rejectInbound(res, commandCheck.reason);
    return;
  }

  // Hash PII (phone number) at rest
  const phoneHash = hashPhoneNumber(fromCheck.value);

  // Every command below reads and mutates this user's shared session, OTP,
  // strategy, and transaction state. Serialize per phone number so
  // concurrent messages from the same user apply in arrival order instead
  // of racing; messages from different users still process in parallel.
  // The idempotency claim happens inside the lock, so an in-process
  // duplicate observes the first delivery's final state.
  const idempotencyKey = deriveIdempotencyKey(
    req.body,
    req.headers?.["i-twilio-idempotency-token"],
  );
  const messageSid =
    typeof req.body?.MessageSid === "string" && req.body.MessageSid !== ""
      ? req.body.MessageSid
      : null;
  // The raw number is only used in-flight to deliver the OTP via SMS (#942);
  // it is never persisted, only the hash is.
  await runExclusive(phoneHash, () =>
    processIdempotently(
      idempotencyKey,
      messageSid,
      phoneHash,
      fromCheck.value,
      commandCheck.value,
      res,
    ),
  );
}

/**
 * Runs a webhook delivery at most once per idempotency key. Twilio may
 * redeliver the same message after a timeout; duplicates of a finished
 * delivery are acknowledged without re-running the command or sending a
 * second reply, and a retryable failure leaves the key open for the next
 * delivery to resume.
 */
async function processIdempotently(
  idempotencyKey: string | null,
  messageSid: string | null,
  phoneHash: string,
  rawPhoneNumber: string,
  messageBody: string,
  res: Response,
): Promise<void> {
  if (!idempotencyKey) {
    logger.warn(
      { phoneHash },
      "Inbound webhook has no MessageSid or idempotency token; processing without deduplication",
    );
    await respondWithCommand(
      null,
      null,
      0,
      phoneHash,
      rawPhoneNumber,
      messageBody,
      res,
    );
    return;
  }

  const store = getIdempotencyStore();
  let claim;
  try {
    claim = await store.claim(
      idempotencyKey,
      { messageSid, phoneHash },
      WEBHOOK_LEASE_MS,
    );
  } catch (error) {
    // Nothing has run yet, so asking Twilio to retry is always safe.
    logger.error(
      { error, phoneHash, idempotencyKey },
      "Failed to claim inbound webhook idempotency key",
    );
    res.status(503).send("Temporarily unable to process message");
    return;
  }

  switch (claim.kind) {
    case "completed":
      logger.info(
        { phoneHash, idempotencyKey },
        "Duplicate inbound webhook after completion; acknowledging without reply",
      );
      res.status(claim.responseStatus).type("text/xml").send(EMPTY_TWIML);
      return;
    case "abandoned":
      logger.error(
        { phoneHash, idempotencyKey },
        "Duplicate inbound webhook for an abandoned attempt with unknown outcome; not re-running command",
      );
      res.status(200).type("text/xml").send(EMPTY_TWIML);
      return;
    case "in_progress":
      // Another worker holds the lease. Signal a retryable conflict so a
      // later redelivery can either see the result or resume a failure.
      logger.info(
        { phoneHash, idempotencyKey },
        "Duplicate inbound webhook while original is still processing",
      );
      res.status(409).send("Message is already being processed");
      return;
    case "acquired":
      await respondWithCommand(
        idempotencyKey,
        store,
        claim.attempt,
        phoneHash,
        rawPhoneNumber,
        messageBody,
        res,
      );
      return;
  }
}

async function respondWithCommand(
  idempotencyKey: string | null,
  store: IdempotencyStore | null,
  attempt: number,
  phoneHash: string,
  rawPhoneNumber: string,
  messageBody: string,
  res: Response,
): Promise<void> {
  const guard = new SideEffectGuard(store, idempotencyKey, attempt);

  let replyXml: string;
  try {
    replyXml = await processWhatsAppMessage(
      phoneHash,
      rawPhoneNumber,
      messageBody,
      guard,
    );
  } catch (error) {
    if (error instanceof LeaseLostError) {
      logger.warn(
        { phoneHash, idempotencyKey, attempt },
        "Lost idempotency lease before side effects; aborting attempt",
      );
      res.status(409).send("Message is already being processed");
      return;
    }

    // Only retryable failures escape processWhatsAppMessage: anything
    // irreversible would already have been converted to a reply.
    logger.warn(
      { error, phoneHash, idempotencyKey, attempt },
      "Retryable failure processing inbound webhook",
    );
    if (store && idempotencyKey) {
      await store
        .fail(
          idempotencyKey,
          attempt,
          error instanceof Error ? error.message : String(error),
        )
        .catch((storeError) =>
          logger.error(
            { error: storeError, idempotencyKey },
            "Failed to record retryable webhook failure",
          ),
        );
    }
    res.status(503).send("Temporarily unable to process message");
    return;
  }

  if (store && idempotencyKey) {
    // If this write fails the record stays `processing`; once its lease
    // expires a duplicate is either re-run (no side effects started, e.g. a
    // balance read) or marked abandoned - never blindly replayed.
    await store
      .complete(idempotencyKey, attempt, 200)
      .catch((storeError) =>
        logger.error(
          { error: storeError, idempotencyKey },
          "Failed to record completed webhook processing",
        ),
      );
  }
  res.status(200).type("text/xml").send(replyXml);
}

/**
 * Executes one inbound command and returns the TwiML reply. Callers must
 * invoke `guard.begin()` before any state-changing step: a transient error
 * raised before that point is rethrown as RetryableWebhookError so the
 * delivery can be retried, while any error after it becomes a terminal
 * user-facing reply, because the command may already have partially applied.
 */
async function processWhatsAppMessage(
  phoneHash: string,
  rawPhoneNumber: string,
  messageBody: string,
  guard: SideEffectGuard,
): Promise<string> {
  const twiml = new MessagingResponse();

  // Enforce per-phone rate limiting
  if (!(await checkRateLimit(phoneHash))) {
    reply(
      twiml,
      "⚠️ Rate limit exceeded. Please wait a minute before sending another message.",
    );
    return twiml.toString();
  }

  // Get or restore user session
  const session = await getSession(phoneHash);
  const intent = parseIntent(messageBody);

  if (intent.strategy) {
    const strategyCheck = boundText(intent.strategy, INPUT_LIMITS.strategy);
    if (!strategyCheck.ok) {
      reply(twiml, SAFE_STRATEGY_REPLY);
      return twiml.toString();
    }
  }

  try {
    // STATE MACHINE FLOW:
    // Flow 1: UNVERIFIED User sends "hi" -> Request OTP verification
    if (session.state === UserState.UNVERIFIED) {
      if (intent.type === "GREETING" || intent.type === "UNKNOWN") {
        await guard.begin();
        const otpCode = await generateOTP(phoneHash);

        try {
          // The OTP is delivered via SMS only; it must never appear in the
          // WhatsApp chat reply (#942).
          const messageSid = await sendOtpSms(rawPhoneNumber, otpCode);
          // Register initial delivery row so retry/escalation can track this SMS
          await applyDeliveryStatus({
            messageSid,
            status: "queued",
            to: rawPhoneNumber,
          });
          await updateState(phoneHash, UserState.AWAITING_OTP);
          reply(
            twiml,
            `👋 Welcome to NeuroWealth AI!\n\nTo secure your wallet, we sent a 6-digit verification code to your phone via SMS. Please reply with that code.\n(Code expires in 5 minutes)`,
          );
        } catch (error) {
          logger.error(
            { error: error instanceof Error ? error.message : error },
            "Failed to send OTP SMS",
          );
          reply(
            twiml,
            "❌ We could not send your verification code. Please try again in a few minutes.",
          );
        }
      } else {
        reply(
          twiml,
          'Welcome to NeuroWealth! Send "hi" to begin account verification.',
        );
      }
      return twiml.toString();
    }

    // Flow 2: AWAITING_OTP -> Verify OTP input code or allow "hi" to request new code
    if (session.state === UserState.AWAITING_OTP) {
      // Allow "hi" to request a new OTP code (helps users recover from lockout/expiry)
      if (intent.type === "GREETING" || intent.type === "UNKNOWN") {
        await guard.begin();
        const otpCode = await generateOTP(phoneHash);

        try {
          const messageSid = await sendOtpSms(rawPhoneNumber, otpCode);
          // Register initial delivery row so retry/escalation can track this SMS
          await applyDeliveryStatus({
            messageSid,
            status: "queued",
            to: rawPhoneNumber,
          });
          reply(
            twiml,
            `🔑 A new verification code was sent to your phone via SMS.\n\n(Code expires in 5 minutes)`,
          );
        } catch (error) {
          logger.error(
            { error: error instanceof Error ? error.message : error },
            "Failed to send OTP SMS",
          );
          reply(
            twiml,
            "❌ We could not send your verification code. Please try again in a few minutes.",
          );
        }
        return twiml.toString();
      }

      if (intent.type === "OTP_CODE" && intent.otpCode) {
        // verifyOTP consumes attempts / the code itself.
        await guard.begin();
        const verification = await verifyOTP(phoneHash, intent.otpCode);

        if (verification.success) {
          await updateState(phoneHash, UserState.VERIFIED);
          const { wallet, isNew } = await createCustodialWallet(phoneHash);
          const shortKey = `${wallet.publicKey.substring(0, 8)}...${wallet.publicKey.substring(wallet.publicKey.length - 8)}`;
          const walletLine = isNew
            ? `🔒 Created your secure custodial Stellar wallet:\nPublic Key: ${shortKey}`
            : `👋 Welcome back! Your existing wallet:\nPublic Key: ${shortKey}`;

          reply(
            twiml,
            `✅ Phone number verified!\n\n` +
              `${walletLine}\n\n` +
              `You can now interact with NeuroWealth entirely through WhatsApp:\n` +
              `• "deposit 100 USDC"\n` +
              `• "what's my balance"\n` +
              `• "withdraw 50"\n` +
              `• "switch to growth"`,
          );
        } else {
          // Reset session to UNVERIFIED on lockout or expiry to unblock the user
          if (verification.shouldResetSession) {
            await updateState(phoneHash, UserState.UNVERIFIED);
          }
          reply(twiml, `❌ ${verification.message}`);
        }
      } else {
        reply(
          twiml,
          'Please enter the 6-digit verification code sent to your phone (valid for 5 minutes), or send "hi" to request a new code.',
        );
      }
      return twiml.toString();
    }

    // Flow 3: VERIFIED User -> Handle Chat Intents
    if (session.state === UserState.VERIFIED) {
      const wallet = await getWallet(phoneHash);
      if (!wallet) {
        // Fallback state sync
        await guard.begin();
        await updateState(phoneHash, UserState.UNVERIFIED);
        reply(
          twiml,
          'Session expired. Please send "hi" to start verification.',
        );
        return twiml.toString();
      }

      // Reject amounts and strategy names the vault contract would refuse
      // before building any transaction.
      const validation = validateIntent(intent);
      if (!validation.ok) {
        reply(twiml, `⚠️ ${validation.error}`);
        return twiml.toString();
      }

      switch (intent.type) {
        case "GREETING": {
          reply(
            twiml,
            `🤖 Hi! I'm your NeuroWealth AI Agent.\n\n` +
              `How can I assist your portfolio today?\n` +
              `1. "balance" - View current portfolio\n` +
              `2. "deposit 100 USDC" - Deposit funds\n` +
              `3. "withdraw 50" - Cash out\n` +
              `4. "switch to growth" - Update strategy`,
          );
          break;
        }

        case "BALANCE":
        case "EARNINGS":
        case "APY": {
          const portfolio = await getPortfolio(phoneHash);
          reply(
            twiml,
            `💰 Your NeuroWealth Portfolio\n\n` +
              `Balance: ${portfolio.balance.toFixed(2)} USDC ($${portfolio.usdEquivalent.toFixed(2)})\n` +
              `Earnings today: +$${portfolio.dailyEarnings.toFixed(2)}\n` +
              `Current APY: ${portfolio.apy}%\n` +
              `Strategy: ${portfolio.strategy}`,
          );
          break;
        }

        case "DEPOSIT": {
          await guard.begin();
          const result = await handleDeposit(
            phoneHash,
            intent.amount as number,
            intent.strategy,
          );
          reply(twiml, `🤖 ${result.message}`);
          break;
        }

        case "WITHDRAW": {
          await guard.begin();
          const result = await handleWithdraw(
            phoneHash,
            intent.amount,
            intent.withdrawAll,
          );
          reply(twiml, `🤖 ${result.message}`);
          break;
        }

        case "STRATEGY": {
          if (!intent.strategy) {
            reply(twiml, "❌ Please specify a valid strategy.");
            break;
          }
          await guard.begin();
          const result = await handleStrategyUpdate(phoneHash, intent.strategy);
          reply(
            twiml,
            result.success ? `✅ ${result.message}` : `❌ ${result.message}`,
          );
          break;
        }

        default: {
          reply(
            twiml,
            `I didn't quite catch that. Try commands like:\n` +
              `• "deposit 50 USDC"\n` +
              `• "what's my balance"\n` +
              `• "withdraw all"\n` +
              `• "switch to conservative"`,
          );
          break;
        }
      }
    }
  } catch (error) {
    if (error instanceof LeaseLostError) throw error;
    if (!guard.hasStarted && isTransientError(error)) {
      throw error instanceof RetryableWebhookError
        ? error
        : new RetryableWebhookError(
            "Transient failure before any side effect",
            { cause: error },
          );
    }

    const reqId = `req-${Math.random().toString(36).substring(2, 9)}`;
    logger.error(
      {
        error,
        phoneHash,
        intentType: intent.type,
        state: session.state,
        reqId,
      },
      "Error processing webhook request",
    );
    reply(
      twiml,
      `❌ An error occurred processing your request. Please try again in a few moments. (Ref: ${reqId})`,
    );
  }

  return twiml.toString();
}

/**
 * Idempotent processing for inbound Twilio WhatsApp webhooks.
 *
 * Twilio can redeliver the same inbound-message webhook (e.g. after our
 * response timed out). Each delivery is keyed by the provider message
 * identifier plus the webhook event identity, and a processing record is
 * claimed *before* the command runs:
 *
 *   - `processing` - an attempt holds a time-bounded lease on the record.
 *   - `completed`  - the command finished (successfully or with a terminal,
 *                    user-facing error). Duplicates are acknowledged without
 *                    re-running the command or sending a second reply.
 *   - `failed`     - a retryable failure happened *before* any side effect
 *                    started, so the next delivery may safely re-run it.
 *   - `abandoned`  - an attempt's lease expired after side effects had
 *                    started (e.g. the process crashed mid-transaction). The
 *                    outcome is unknown, so it is never re-run automatically.
 *
 * Every attempt carries a fencing token (`attempt`); writes from an attempt
 * whose lease was taken over by a later one are rejected.
 */
import { query } from './db';

export type InboundWebhookStatus = 'processing' | 'completed' | 'failed' | 'abandoned';

export type ClaimResult =
  | { kind: 'acquired'; attempt: number }
  | { kind: 'completed'; responseStatus: number }
  | { kind: 'in_progress' }
  | { kind: 'abandoned' };

export interface ClaimMetadata {
  messageSid: string | null;
  phoneHash: string;
}

export interface IdempotencyStore {
  /** Atomically claims the key for a new processing attempt, or reports why it cannot be. */
  claim(key: string, meta: ClaimMetadata, leaseMs: number): Promise<ClaimResult>;
  /** Records that the attempt is about to mutate state. Returns false if the attempt lost its lease. */
  markSideEffectsStarted(key: string, attempt: number): Promise<boolean>;
  /** Marks the attempt as finished; duplicates will now be acknowledged without re-running. */
  complete(key: string, attempt: number, responseStatus: number): Promise<void>;
  /** Marks the attempt as a retryable failure so the next delivery may resume it. */
  fail(key: string, attempt: number, error: string): Promise<void>;
}

/** Thrown for failures that happened before any side effect, so redelivery can safely re-run the command. */
export class RetryableWebhookError extends Error {
  constructor(message: string, options?: { cause?: unknown }) {
    super(message);
    this.name = 'RetryableWebhookError';
    if (options && 'cause' in options) {
      (this as { cause?: unknown }).cause = options.cause;
    }
  }
}

/** Thrown when another attempt took over this delivery's lease before side effects began. */
export class LeaseLostError extends Error {
  constructor() {
    super('Idempotency lease was taken over by another attempt');
    this.name = 'LeaseLostError';
  }
}

const INBOUND_MESSAGE_EVENT = 'inbound-message';

const TRANSIENT_ERROR_CODES = new Set([
  'ECONNREFUSED',
  'ECONNRESET',
  'ETIMEDOUT',
  'EPIPE',
  'EAI_AGAIN',
  'ENOTFOUND',
  // PostgreSQL SQLSTATEs: serialization failure, deadlock, too many
  // connections, admin shutdown, cannot connect now.
  '40001',
  '40P01',
  '53300',
  '57P01',
  '57P03',
]);

/** True for infrastructure errors where retrying the same request may succeed. */
export function isTransientError(error: unknown): boolean {
  if (error instanceof RetryableWebhookError) return true;
  const code = (error as { code?: unknown } | null)?.code;
  if (typeof code !== 'string') return false;
  // SQLSTATE class 08 = connection exception.
  return TRANSIENT_ERROR_CODES.has(code) || /^08[0-9A-Z]{3}$/.test(code);
}

/**
 * Derives the idempotency key for an inbound WhatsApp webhook.
 *
 * Twilio's MessageSid identifies the inbound message and is stable across
 * redeliveries; it is scoped by AccountSid and by the webhook event type so
 * a different event about the same message can never collide with it. When
 * MessageSid is absent, Twilio's `I-Twilio-Idempotency-Token` header (also
 * stable across retries) is used instead. Returns null when neither exists.
 */
export function deriveIdempotencyKey(
  body: Record<string, unknown> | undefined,
  idempotencyTokenHeader?: string | string[]
): string | null {
  const accountSid = typeof body?.AccountSid === 'string' && body.AccountSid ? body.AccountSid : '-';
  const messageSid = typeof body?.MessageSid === 'string' ? body.MessageSid.trim() : '';
  if (messageSid) {
    return `twilio:${INBOUND_MESSAGE_EVENT}:${accountSid}:${messageSid}`;
  }

  const token = Array.isArray(idempotencyTokenHeader) ? idempotencyTokenHeader[0] : idempotencyTokenHeader;
  if (token && token.trim()) {
    return `twilio:${INBOUND_MESSAGE_EVENT}:${accountSid}:token:${token.trim()}`;
  }

  return null;
}

/**
 * Tracks whether the current attempt has started mutating state. Errors
 * raised before `begin()` are safe to retry; errors after it are not, since
 * the command may already have partially applied.
 */
export class SideEffectGuard {
  private started = false;

  constructor(
    private readonly store: IdempotencyStore | null,
    private readonly key: string | null,
    private readonly attempt: number
  ) {}

  get hasStarted(): boolean {
    return this.started;
  }

  async begin(): Promise<void> {
    if (this.started) return;
    if (this.store && this.key) {
      const stillOwned = await this.store.markSideEffectsStarted(this.key, this.attempt);
      if (!stillOwned) throw new LeaseLostError();
    }
    this.started = true;
  }
}

// ── PostgreSQL store ─────────────────────────────────────────────────────────

export class PostgresIdempotencyStore implements IdempotencyStore {
  async claim(key: string, meta: ClaimMetadata, leaseMs: number): Promise<ClaimResult> {
    // A single atomic upsert decides ownership: a new key is inserted, and an
    // existing one is only taken over if its last attempt failed retryably or
    // its lease expired before any side effect started.
    const claimed = await query(
      `INSERT INTO whatsapp_inbound_webhooks
         (idempotency_key, message_sid, phone_hash, status, attempt_count, side_effects_started,
          lease_expires_at, created_at, updated_at)
       VALUES ($1, $2, $3, 'processing', 1, FALSE, NOW() + $4::double precision * INTERVAL '1 millisecond', NOW(), NOW())
       ON CONFLICT (idempotency_key) DO UPDATE
         SET status = 'processing',
             attempt_count = whatsapp_inbound_webhooks.attempt_count + 1,
             lease_expires_at = EXCLUDED.lease_expires_at,
             last_error = NULL,
             updated_at = NOW()
       WHERE whatsapp_inbound_webhooks.status = 'failed'
          OR (whatsapp_inbound_webhooks.status = 'processing'
              AND whatsapp_inbound_webhooks.lease_expires_at < NOW()
              AND NOT whatsapp_inbound_webhooks.side_effects_started)
       RETURNING attempt_count`,
      [key, meta.messageSid, meta.phoneHash, leaseMs]
    );
    if (claimed.rows.length > 0) {
      return { kind: 'acquired', attempt: Number(claimed.rows[0].attempt_count) };
    }

    const existing = await query(
      `SELECT status, response_status, side_effects_started, lease_expires_at < NOW() AS lease_expired
         FROM whatsapp_inbound_webhooks WHERE idempotency_key = $1`,
      [key]
    );
    const row = existing.rows[0];
    if (!row) {
      // Only reachable if the row was deleted between the two statements.
      throw new RetryableWebhookError('Idempotency record vanished during claim');
    }

    return this.classifyExisting(key, row);
  }

  private async classifyExisting(key: string, row: Record<string, unknown>): Promise<ClaimResult> {
    if (row.status === 'completed') {
      return { kind: 'completed', responseStatus: Number(row.response_status) || 200 };
    }
    if (row.status === 'abandoned') {
      return { kind: 'abandoned' };
    }
    if (row.status === 'processing' && row.lease_expired && row.side_effects_started) {
      await query(
        `UPDATE whatsapp_inbound_webhooks
            SET status = 'abandoned',
                last_error = 'lease expired after side effects started; manual reconciliation required',
                updated_at = NOW()
          WHERE idempotency_key = $1 AND status = 'processing'`,
        [key]
      );
      return { kind: 'abandoned' };
    }
    return { kind: 'in_progress' };
  }

  async markSideEffectsStarted(key: string, attempt: number): Promise<boolean> {
    const res = await query(
      `UPDATE whatsapp_inbound_webhooks
          SET side_effects_started = TRUE, updated_at = NOW()
        WHERE idempotency_key = $1 AND attempt_count = $2 AND status = 'processing'`,
      [key, attempt]
    );
    return (res.rowCount ?? 0) > 0;
  }

  async complete(key: string, attempt: number, responseStatus: number): Promise<void> {
    await query(
      `UPDATE whatsapp_inbound_webhooks
          SET status = 'completed', response_status = $3, completed_at = NOW(), updated_at = NOW()
        WHERE idempotency_key = $1 AND attempt_count = $2 AND status = 'processing'`,
      [key, attempt, responseStatus]
    );
  }

  async fail(key: string, attempt: number, error: string): Promise<void> {
    await query(
      `UPDATE whatsapp_inbound_webhooks
          SET status = 'failed', last_error = $3, updated_at = NOW()
        WHERE idempotency_key = $1 AND attempt_count = $2 AND status = 'processing'`,
      [key, attempt, error.slice(0, 500)]
    );
  }
}

// ── In-memory store (tests, single-process development) ─────────────────────

interface MemoryRecord {
  status: InboundWebhookStatus;
  attempt: number;
  sideEffectsStarted: boolean;
  leaseExpiresAt: number;
  responseStatus: number | null;
  lastError: string | null;
}

/**
 * Same semantics as the PostgreSQL store. Each operation yields to the event
 * loop first (like a real round-trip) and then runs synchronously, so it is
 * atomic with respect to concurrent callers - mirroring row-level atomicity.
 */
export class InMemoryIdempotencyStore implements IdempotencyStore {
  readonly records = new Map<string, MemoryRecord>();

  constructor(private readonly now: () => number = Date.now) {}

  async claim(key: string, _meta: ClaimMetadata, leaseMs: number): Promise<ClaimResult> {
    await Promise.resolve();
    const now = this.now();
    const record = this.records.get(key);

    if (!record) {
      this.records.set(key, {
        status: 'processing',
        attempt: 1,
        sideEffectsStarted: false,
        leaseExpiresAt: now + leaseMs,
        responseStatus: null,
        lastError: null,
      });
      return { kind: 'acquired', attempt: 1 };
    }

    const leaseExpired = record.leaseExpiresAt < now;
    if (record.status === 'failed' || (record.status === 'processing' && leaseExpired && !record.sideEffectsStarted)) {
      record.status = 'processing';
      record.attempt += 1;
      record.leaseExpiresAt = now + leaseMs;
      record.lastError = null;
      return { kind: 'acquired', attempt: record.attempt };
    }

    if (record.status === 'completed') {
      return { kind: 'completed', responseStatus: record.responseStatus ?? 200 };
    }
    if (record.status === 'abandoned') {
      return { kind: 'abandoned' };
    }
    if (leaseExpired && record.sideEffectsStarted) {
      record.status = 'abandoned';
      record.lastError = 'lease expired after side effects started; manual reconciliation required';
      return { kind: 'abandoned' };
    }
    return { kind: 'in_progress' };
  }

  async markSideEffectsStarted(key: string, attempt: number): Promise<boolean> {
    await Promise.resolve();
    const record = this.owned(key, attempt);
    if (!record) return false;
    record.sideEffectsStarted = true;
    return true;
  }

  async complete(key: string, attempt: number, responseStatus: number): Promise<void> {
    await Promise.resolve();
    const record = this.owned(key, attempt);
    if (!record) return;
    record.status = 'completed';
    record.responseStatus = responseStatus;
  }

  async fail(key: string, attempt: number, error: string): Promise<void> {
    await Promise.resolve();
    const record = this.owned(key, attempt);
    if (!record) return;
    record.status = 'failed';
    record.lastError = error;
  }

  private owned(key: string, attempt: number): MemoryRecord | undefined {
    const record = this.records.get(key);
    return record && record.attempt === attempt && record.status === 'processing' ? record : undefined;
  }
}

// ── Store selection ──────────────────────────────────────────────────────────

let activeStore: IdempotencyStore = new PostgresIdempotencyStore();

export function getIdempotencyStore(): IdempotencyStore {
  return activeStore;
}

/** Swaps the backing store (tests). */
export function setIdempotencyStore(store: IdempotencyStore): void {
  activeStore = store;
}

export const WEBHOOK_LEASE_MS = parseInt(process.env.WHATSAPP_WEBHOOK_LEASE_MS || '120000', 10);
